  1115	          FROM unnest(entity_ids) AS linked_id
  1116	          WHERE NOT (linked_id = ANY(${entityTreeIdsLiteral}::bigint[]))
  1117	        )
  1118	        WHERE entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1119	      `;
  1120	
  1121	      await tx`
  1122	        DELETE FROM feeds
  1123	        WHERE entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1124	          AND entity_ids <@ ${entityTreeIdsLiteral}::bigint[]
  1125	      `;
  1126	      await tx`
  1127	        UPDATE feeds
  1128	        SET entity_ids = ARRAY(
  1129	          SELECT linked_id
  1130	          FROM unnest(entity_ids) AS linked_id
  1131	          WHERE NOT (linked_id = ANY(${entityTreeIdsLiteral}::bigint[]))
  1132	        )
  1133	        WHERE entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1134	      `;
  1135	
  1136	      // Detach event references instead of blocking on them: `events` is
  1137	      // append-only (never DELETE), but the platform's own lifecycle events
  1138	      // (change audits etc.) reference fresh entities immediately, so a hard
  1139	      // delete must prune the tree ids out of events.entity_ids — the rows
  1140	      // survive as history, they just stop pointing at deleted entities.
  1141	      // Batched so a large history can't push one UPDATE past
  1142	      // statement_timeout; still atomic (all batches share this transaction).
  1143	      const EVENT_DETACH_BATCH = 5000;
  1144	      for (;;) {
  1145	        const detached = await tx<{ id: number }>`
  1146	          UPDATE events e
  1147	          SET entity_ids = ARRAY(
  1148	            SELECT linked_id
  1149	            FROM unnest(e.entity_ids) AS linked_id
  1150	            WHERE NOT (linked_id = ANY(${entityTreeIdsLiteral}::bigint[]))
  1151	          )
  1152	          WHERE e.id IN (
  1153	            SELECT id FROM events
  1154	            WHERE entity_ids && ${entityTreeIdsLiteral}::bigint[]
  1155	            LIMIT ${EVENT_DETACH_BATCH}
  1156	          )
  1157	          RETURNING e.id
  1158	        `;
  1159	        if (detached.length < EVENT_DETACH_BATCH) break;
  1160	      }
  1161	
  1162	      await tx`
  1163	        DELETE FROM entities
  1164	        WHERE id = ANY(${entityTreeIdsLiteral}::bigint[])
  1165	      `;
  1166	    });
  1167	
  1168	    return {
  1169	      message:
  1170	        report.events_detached > 0
  1171	          ? `Entity and all descendants deleted; ${report.events_detached} event rows kept as history and detached`
  1172	          : 'Entity and all descendants deleted successfully',
  1173	      deleted: entityTreeIds.length,
  1174	      tree: report,
  1175	    };
  1176	  }
  1177	
  1178	  if (opts?.dryRun) {
  1179	    return {
  1180	      message: 'Dry run: entity would be soft-deleted',
  1181	      deleted: 0,
  1182	      dry_run: true,
  1183	    };
  1184	  }
  1185	
  1186	  // Soft delete: set deleted_at timestamp
  1187	  await sql`
  1188	    UPDATE entities
  1189	    SET deleted_at = current_timestamp, updated_at = current_timestamp
  1190	    WHERE id = ${entityId} AND deleted_at IS NULL
  1191	  `;
  1192	
  1193	  return {
  1194	    message: 'Entity soft-deleted successfully',
  1195	    deleted: 1,
  1196	  };
  1197	}
