 823	/**
 824	 * Get entity by ID
 825	 * Only returns entity if user has read access (own org or public)
 826	 */
 827	export async function getEntity(
 828		entityId: number,
 829		_env: Env,
 830		ctx: ToolContext,
 831		opts?: { includeDeleted?: boolean },
 832	): Promise<CreatedEntity | null> {
 833	  const sql = getDb();
 834	  if (!ctx.organizationId) return null;
 835	  const includeDeleted = opts?.includeDeleted ?? false;
1330		args?: ManageEntityArgs,
1331	): Promise<ManageEntityResult> {
1332		// Get entity info before deletion
1333		const entity = await getEntity(entityId, env, ctx);
1334		if (!entity) {
1335			throw new Error(`Entity with ID ${entityId} not found`);
1336		}
1337	
1338		const deleteActor = await actingPrincipalFor(args, ctx);
1339		const attribution = attributionFor(deleteActor);
1340		const current = {
1341			id: entity.id,
1342			entity_type: entity.entity_type,
1343			name: entity.name,
1344			slug: entity.slug,
1345			parent_id: entity.parent_id,
1346			metadata: entity.metadata ?? {},
