462		db: DbClient = getDb(),
463	): Promise<ApplyUnmergeResult> {
464	  const { orgId, loserId, unmergedBy } = params;
465	
466	  return db.begin(async (tx) => {
467	    // Discover the winner WITHOUT locking first: we can't name the winner until
468	    // we read merged_into, but taking the loser's lock here would grab the
469	    // loser's row before the winner's — inverting applyMerge's lowest-id-first
470	    // order and deadlocking a concurrent merge of the same pair whenever
471	    // winnerId < loserId.
472	    const [probe] = (await tx<{ merged_into: number | null }>`
473	      SELECT merged_into
474	      FROM entities
475	      WHERE organization_id = ${orgId} AND id = ${loserId}
476	    `) as Array<{ merged_into: number | null }>;
477	    if (!probe) {
478	      throw new Error(`applyUnmerge: entity ${loserId} not found in org`);
479	    }
480	    if (probe.merged_into === null) {
481				throw new Error(
482					`applyUnmerge: entity ${loserId} is not merged into anything`,
483				);
484	    }
485	    const winnerId = Number(probe.merged_into);
486	
487	    // Lock BOTH rows in one statement, ascending id (matches applyMerge), so no
488	    // path ever holds these two locks in opposing orders.
489			const [lo, hi] =
490				loserId < winnerId ? [loserId, winnerId] : [winnerId, loserId];
491	    const locked = (await tx<{
492	      id: number;
493	      merged_into: number | null;
494				metadata: Record<string, unknown>;
495				field_controls: Record<string, unknown>;
496	    }>`
497	      SELECT id, merged_into, metadata, field_controls
498	      FROM entities
499	      WHERE organization_id = ${orgId} AND id IN (${lo}, ${hi})
500	      ORDER BY id
501	      FOR UPDATE
502	    `) as Array<{
503				id: number;
504				merged_into: number | null;
505				metadata: Record<string, unknown>;
506				field_controls: Record<string, unknown>;
507			}>;
508	
509	    // Re-validate under lock: merged_into can move between the unlocked probe and
510	    // acquiring the lock (a racing unmerge/merge). Fail closed if it changed so
511	    // we never operate on a stale winner we didn't lock.
512	    const loserRow = locked.find((row) => Number(row.id) === loserId);
513	    if (!loserRow) {
514	      throw new Error(`applyUnmerge: entity ${loserId} not found in org`);
515	    }
516	    if (
517	      loserRow.merged_into === null ||
518	      Number(loserRow.merged_into) !== winnerId
519	    ) {
520				throw new Error(
521					`applyUnmerge: entity ${loserId} is not merged into anything`,
522				);
523	    }
524	
525			const [operation] = await tx<{
526				id: number;
527				winner_entity_id: number;
528				ledger: {
529					winner: {
530						metadataBefore: Record<string, unknown>;
531						metadataAfter: Record<string, unknown>;
532						fieldControlsBefore: Record<string, unknown>;
533						fieldControlsAfter: Record<string, unknown>;
534					};
535					identities: Array<{
536						id: number;
537						mergedFromEntityId: number | null;
538					}>;
539					redirectedEntityIds: number[];
540					relationships: Array<{
541						id: number;
542						before: {
543							fromEntityId: number;
544							toEntityId: number;
545							deletedAt: string | null;
546						};
547						after: {
548							fromEntityId: number;
549							toEntityId: number;
550							deletedAt: string | null;
551						};
552					}>;
553				};
554			}>`
555	      SELECT id, winner_entity_id, ledger
556	      FROM entity_merge_operations
557	      WHERE organization_id = ${orgId}
558	        AND loser_entity_id = ${loserId}
559	        AND status = 'active'
560	      ORDER BY id DESC
561	      LIMIT 1
562	      FOR UPDATE
563	    `;
564	
565			if (operation) {
566				if (Number(operation.winner_entity_id) !== winnerId) {
567					throw new Error(
568						"applyUnmerge: a later merge changed the canonical entity; undo that merge first",
569					);
570				}
571				const winnerRow = locked.find((row) => Number(row.id) === winnerId);
572				if (!winnerRow) {
573					throw new Error(`applyUnmerge: winner ${winnerId} not found in org`);
574				}
575				const ledger = operation.ledger;
576				if (
577					!isDeepStrictEqual(
578						winnerRow.metadata ?? {},
579						ledger.winner.metadataAfter,
580					) ||
581					!isDeepStrictEqual(
582						winnerRow.field_controls ?? {},
583						ledger.winner.fieldControlsAfter,
584					)
585				) {
586					throw new Error(
587						"applyUnmerge: canonical attributes changed after this merge; exact undo is unsafe",
588					);
589				}
590	
591				const identityIds = ledger.identities.map((item) => item.id);
592				const currentIdentities =
593					identityIds.length > 0
594						? await tx<{
595								id: number;
596								entity_id: number;
597								merged_from_entity_id: number | null;
598								deleted_at: Date | string | null;
599							}>`
600	            SELECT id, entity_id, merged_from_entity_id, deleted_at
601	            FROM entity_identities
602	            WHERE organization_id = ${orgId}
603	              AND id = ANY(${pgBigintArray(identityIds)}::bigint[])
604	            ORDER BY id
605	            FOR UPDATE
606	          `
607						: [];
608				const currentIdentityById = new Map(
609					currentIdentities.map((row) => [Number(row.id), row]),
610				);
611				for (const item of ledger.identities) {
612					const current = currentIdentityById.get(item.id);
613					const expectedMarker = item.mergedFromEntityId ?? loserId;
614					if (
615						!current ||
616						Number(current.entity_id) !== winnerId ||
617						Number(current.merged_from_entity_id) !== expectedMarker ||
618						current.deleted_at !== null
619					) {
620						throw new Error(
621							`applyUnmerge: identity ${item.id} changed after this merge; exact undo is unsafe`,
622						);
623					}
624				}
625	
626				const relationshipIds = ledger.relationships.map((item) => item.id);
627				const currentRelationships =
628					relationshipIds.length > 0
629						? await tx<{
630								id: number;
631								from_entity_id: number;
632								to_entity_id: number;
633								deleted_at: Date | string | null;
634							}>`
635	            SELECT id, from_entity_id, to_entity_id, deleted_at
636	            FROM entity_relationships
637	            WHERE organization_id = ${orgId}
638	              AND id = ANY(${pgBigintArray(relationshipIds)}::bigint[])
639	            ORDER BY id
640	            FOR UPDATE
641	          `
642						: [];
643				const currentById = new Map(
644					currentRelationships.map((row) => [Number(row.id), row]),
645				);
646				for (const item of ledger.relationships) {
647					const current = currentById.get(item.id);
648					const currentDeletedAt =
649						current?.deleted_at == null
650							? null
651							: new Date(current.deleted_at).toISOString();
652					if (
653						!current ||
654						Number(current.from_entity_id) !== item.after.fromEntityId ||
655						Number(current.to_entity_id) !== item.after.toEntityId ||
656						currentDeletedAt !== item.after.deletedAt
657					) {
658						throw new Error(
659							`applyUnmerge: relationship ${item.id} changed after this merge; exact undo is unsafe`,
660						);
661					}
662				}
663	
664				for (const item of ledger.relationships) {
665					await tx`
666	          UPDATE entity_relationships
667	          SET from_entity_id = ${item.before.fromEntityId},
668	              to_entity_id = ${item.before.toEntityId},
669	              deleted_at = ${item.before.deletedAt},
670	              updated_at = current_timestamp
671	          WHERE organization_id = ${orgId} AND id = ${item.id}
672	        `;
673				}
674				const redirectedEntityIds = ledger.redirectedEntityIds ?? [];
675				if (redirectedEntityIds.length > 0) {
676					const restoredRedirects = await tx<{ id: number }>`
677	          UPDATE entities
678	          SET merged_into = ${loserId}, updated_at = current_timestamp
679	          WHERE organization_id = ${orgId}
680	            AND id = ANY(${pgBigintArray(redirectedEntityIds)}::bigint[])
681	            AND merged_into = ${winnerId}
682	          RETURNING id
683	        `;
684					if (restoredRedirects.length !== redirectedEntityIds.length) {
685						throw new Error(
686							"applyUnmerge: a flattened redirect changed after this merge; exact undo is unsafe",
687						);
688					}
689				}
690				await tx`
691	        UPDATE entities
692	        SET metadata = ${tx.json(ledger.winner.metadataBefore)},
693	            field_controls = ${tx.json(ledger.winner.fieldControlsBefore)},
694	            updated_at = current_timestamp
695	        WHERE organization_id = ${orgId} AND id = ${winnerId}
696	      `;
697			}
698	
699			// 1. Restore every identity this operation moved, including identities an
700			//    inner merge had already placed on the loser. Legacy operations have no
701			//    ledger, so they retain the marker-based single-merge fallback.
702			let restored: Array<{ id: number }>;
703			if (operation) {
704				restored = [];
705				for (const identity of operation.ledger.identities) {
706					const rows = await tx<{ id: number }>`
707	          UPDATE entity_identities
708	          SET entity_id = ${loserId},
709	              merged_from_entity_id = ${identity.mergedFromEntityId},
710	              updated_at = current_timestamp
711	          WHERE organization_id = ${orgId} AND id = ${identity.id}
712	          RETURNING id
713	        `;
714					restored.push(...rows);
715				}
716			} else {
717				restored = (await tx<{ id: number }>`
718	      UPDATE entity_identities
719	      SET entity_id = ${loserId},
720	          merged_from_entity_id = NULL,
721	          updated_at = current_timestamp
722	      WHERE organization_id = ${orgId}
723	        AND entity_id = ${winnerId}
724	        AND merged_from_entity_id = ${loserId}
725	        AND deleted_at IS NULL
726	      RETURNING id
727	    `) as Array<{ id: number }>;
728			}
729	
730			// 2. Un-forward and un-tombstone the loser. Ledger-backed merges restored
731			//    redirects flattened through it above; legacy merges retain the old
732			//    single-row behavior because no redirect history exists for them.
733	    await tx`
734	      UPDATE entities
735	      SET merged_into = NULL, deleted_at = NULL, updated_at = current_timestamp
736	      WHERE organization_id = ${orgId} AND id = ${loserId}
737	    `;
738			if (operation) {
739				await tx`
740	        UPDATE entity_merge_operations
741	        SET status = 'undone', undone_at = current_timestamp, undone_by = ${unmergedBy}
742	        WHERE id = ${operation.id}
743	      `;
744			}
745	
746	    logger.info(
747	      {
748	        orgId,
749	        loserId,
750	        winnerId,
751	        unmergedBy,
752	        restoredIdentities: restored.length,
753	      },
754				"entity merge reversed",
755	    );
756	
757	    return {
758	      winnerId,
759	      restoredIdentities: restored.length,
760	    };

   1	/**
   2	 * Declarative entity-link resolver at event ingestion.
   3	 *
   4	 * A connector declares `eventKinds[kind].attributions[]` rules. Each attribution
   5	 * maps event identifier fields (phone, email, wa_jid, ...) to a target entity.
   6	 * The ingestion pipeline:
   7	 *   1) Extracts + normalizes identifiers from each event.
   8	 *   2) Looks them up in the normalized `entity_identities` table
   9	 *      (UNIQUE per (org, namespace, identifier)).
  10	 *   3) Links to the matched entity, creates on miss (when autoCreate=true),
  11	 *      logs a merge candidate when one event's identifiers resolve to
  12	 *      multiple distinct entities.
  13	 *   4) Merges declared `traits` onto entities.metadata per behavior.
  14	 *
  15	 * Never mutates `events.entity_ids` — events stay immutable, JOIN-at-read
  16	 * recovers the relationship via entity_identities.
  17	 */
  18	
  19	import { randomBytes } from 'node:crypto';
  20	import {
  21	  ACL_RESOURCE_TYPE_SLUG,
  22	  type EntityIdentitySpec,
  23	  type EntityLinkPredicate,
  24	  type EntityTraitSpec,
  25	  type EventAttributionRule,
  26	} from '@lobu/connector-sdk';
  27	import { normalizeIdentifier } from '@lobu/connector-sdk/identity-normalize';
  28	import { ensureResourceEntityType } from '../authz/acl-resource-type';
  29	import { type DbClient, getDb, pgTextArray } from '../db/client';
  30	import { normalizeConnectorIdentityValue } from '../identity/connector-identity-modules';
  31	import logger from './logger';
  32	import { getValueAtPath } from './object-path';
  33	import { TtlCache } from './ttl-cache';
  34	
  35	interface BatchItem {
  36	  origin_type?: string;
  37	  metadata?: Record<string, unknown>;
  38	  title?: string | null;
  39	}
  40	
  41	type ResolvedEventAttributionRule = {
  42	  role: EventAttributionRule['role'];
  43	  entityType: string;
  44	  autoCreate?: boolean;
  45	  createWhen?: EntityLinkPredicate;
  46	  titlePath?: string;
  47	  identities: EntityIdentitySpec[];
  48	  traits?: Record<string, EntityTraitSpec>;
  49	};
  50	
  51	interface RuleMap {
  52	  [kind: string]: ResolvedEventAttributionRule[];
  53	}
  54	
  55	type EventKindAttributionDefinition = {
  56	  attributions?: EventAttributionRule[];
  57	};
  58	
  59	function resolveEventAttributions(
  60	  def: EventKindAttributionDefinition | undefined
  61	): ResolvedEventAttributionRule[] {
  62	  return (def?.attributions ?? []).flatMap((rule) => {
  63	    const identities = rule.target.identities;
  64	    if (!rule.target.entityType || !Array.isArray(identities) || identities.length === 0) {
  65	      return [];
  66	    }
  67	    return [
  68	      {
  69	        role: rule.role,
  70	        entityType: rule.target.entityType,
  71	        autoCreate: rule.autoCreate,
  72	        createWhen: rule.target.createWhen,
  73	        titlePath: rule.target.titlePath,
  74	        identities,
  75	        traits: rule.traits,
  76	      },
  77	    ];
  78	  });
  79	}
  80	
  81	const RULES_CACHE_TTL_MS = 60_000;
  82	// Per-pod caches — no cross-replica sharing.
  83	const rulesCache = new TtlCache<RuleMap>(RULES_CACHE_TTL_MS);
  84	const creatorCache = new TtlCache<string | null>(RULES_CACHE_TTL_MS);
  85	
  86	async function resolveOrgCreator(orgId: string): Promise<string | null> {
  87	  return creatorCache.getOrSet(orgId, async () => {
  88	    const sql = getDb();
  89	    const rows = await sql<{ userId: string }>`
  90	      SELECT "userId"
  91	      FROM "member"
  92	      WHERE "organizationId" = ${orgId}
  93	      ORDER BY CASE role WHEN 'owner' THEN 0 WHEN 'admin' THEN 1 ELSE 2 END,
  94	               "createdAt" ASC
  95	      LIMIT 1
  96	    `;
  97	    return rows.length > 0 ? rows[0].userId : null;
  98	  });
  99	}
