 101	function randomSlug(entityType: string): string {
 102	  const prefix =
 103	    entityType
 104	      .replace(/^\$/, '')
 105	      .replace(/[^a-z0-9]+/gi, '-')
 106	      .toLowerCase() || 'entity';
 107	  return `${prefix}-${randomBytes(5).toString('hex')}`;
 108	}
