 110	async function loadEventAttributionRules(params: {
 111	  connectorKey: string;
 112	  feedKey: string;
 113	  orgId: string;
 114	}): Promise<RuleMap> {
 115	  const cacheKey = `${params.orgId}:${params.connectorKey}:${params.feedKey}`;
 116	  return rulesCache.getOrSet(cacheKey, async () => {
 117	    const sql = getDb();
 118	    const rows = await sql`
 119	      SELECT feeds_schema
 120	      FROM connector_definitions
 121	      WHERE key = ${params.connectorKey}
 122	        AND organization_id = ${params.orgId}
 123	      LIMIT 1
 124	    `;
 125	
 126	    const result: RuleMap = {};
 127	    const feedsSchema = rows[0]?.feeds_schema as Record<string, any> | null | undefined;
 128	    const feedDef = feedsSchema?.[params.feedKey];
 129	    const eventKinds = feedDef?.eventKinds as Record<string, EventKindAttributionDefinition> | undefined;
 130	    if (eventKinds) {
 131	      for (const [kind, def] of Object.entries(eventKinds)) {
 132	        const resolved = resolveEventAttributions(def);
 133	        if (resolved.length > 0) result[kind] = resolved;
 134	      }
 135	    }
 136	    return result;
 137	  });
 138	}
