 278	/**
 279	 * Connector-owned namespaces are normalized by their own connector module
 280	 * (assembled in identity/connector-identity-modules.ts); generic namespaces
 281	 * fall back to the SDK's normalizer.
 282	 */
 283	function normalizeIdentityValue(namespace: string, raw: string): string | null {
 284	  const connector = normalizeConnectorIdentityValue(namespace, raw);
 285	  if (connector !== undefined) return connector;
 286	  return normalizeIdentifier(namespace, raw);
 287	}
