const r = await tools.exec_command({cmd:"node --no-node-snapshot -e '
const ivm=require("isolated-vm-next");
const {performance}=require("node:perf_hooks");
const source=`(() => { const c=globalThis.__ctx; let n=0; for (const [k,v] of Object.entries(c.candidate.metadata)) n += k.length + String(v).length; return {deny:null,patch:n%2?{checked:true}:null}; })()`;
function payload(bytes){const s="x".repeat(Math.max(0,bytes-200));return {op:"update",current:{id:1,status:"draft",metadata:{}},candidate:{id:1,status:"posted",metadata:{blob:s}},reads:{period:{closed:false}}};}
function stats(name,a){a.sort((x,y)=>x-y);const q=p=>a[Math.min(a.length-1,Math.floor(a.length*p))];console.log(JSON.stringify({name,n:a.length,mean_ms:+(a.reduce((x,y)=>x+y,0)/a.length).toFixed(3),p50_ms:+q(.5).toFixed(3),p95_ms:+q(.95).toFixed(3),p99_ms:+q(.99).toFixed(3),max_ms:+a[a.length-1].toFixed(3)}));}
async function cold(n,p){const a=[];for(let i=0;i<n;i++){const t=performance.now();const iso=new ivm.Isolate({memoryLimit:8});const ctx=await iso.createContext();const script=await iso.compileScript(source);await ctx.global.set("__ctx",new ivm.ExternalCopy(p).copyInto());await script.run(ctx,{timeout:10,copy:true});iso.dispose();a.push(performance.now()-t);}return a;}
async function pooledFreshContext(n,p){const iso=new ivm.Isolate({memoryLimit:8});const script=await iso.compileScript(source);const a=[];for(let i=0;i<n;i++){const t=performance.now();const ctx=await iso.createContext();await ctx.global.set("__ctx",new ivm.ExternalCopy(p).copyInto());await script.run(ctx,{timeout:10,copy:true});ctx.release();a.push(performance.now()-t);}iso.dispose();return a;}
async function pooledContext(n,p){const iso=new ivm.Isolate({memoryLimit:8});const script=await iso.compileScript(source);const ctx=await iso.createContext();const a=[];for(let i=0;i<n;i++){const t=performance.now();await ctx.global.set("__ctx",new ivm.ExternalCopy(p).copyInto());await script.run(ctx,{timeout:10,copy:true});a.push(performance.now()-t);}iso.dispose();return a;}
(async()=>{for(const bytes of [1024,16384,65536]){const p=payload(bytes);stats(`cold-${bytes}`,await cold(150,p));stats(`pool-fresh-context-${bytes}`,await pooledFreshContext(1000,p));stats(`pool-reused-context-${bytes}`,await pooledContext(1000,p));}})().catch(e=>{console.error(e);process.exit(1)});'","workdir":"/Users/burakemre/Code/lobu","yield_time_ms":30000,"max_output_tokens":12000});
