 15	 * Grabs a stack trace of the runaway script
 16	 */
 17	class TimeoutRunner final : public Runnable {
 18		public:
 19			struct State {
 20				std::condition_variable cv;
 21				std::mutex mutex;
 22				std::string stack_trace;
 23				bool did_finish = false;
 24				bool did_release = false;
 25				bool did_terminate = false;
 26				bool did_timeout = false;
 27			};
 28	
 29			explicit TimeoutRunner(State& state) : state{state} {}
 30			TimeoutRunner(const TimeoutRunner&) = delete;
 31			auto operator=(const TimeoutRunner&) -> TimeoutRunner& = delete;
 32	
 33			~TimeoutRunner() final {
 34				std::lock_guard<std::mutex> lock{state.mutex};
 35				state.did_release = true;
 36				state.cv.notify_all();
 37			}
 38	
 39			void Run() final {
 40				bool will_terminate = [&]() {
 41					std::lock_guard<std::mutex> lock{state.mutex};
 42					if (state.did_finish) {
 43						return false;
 44					} else {
 45						state.did_terminate = true;
 46						return true;
 47					}
 48				}();
 49				if (will_terminate) {
 50					auto& env = IsolateEnvironment::GetCurrent();
 51					auto* isolate = env.GetIsolate();
 52					state.stack_trace = StackTraceHolder::RenderSingleStack(v8::StackTrace::CurrentStackTrace(isolate, 10));
 53					isolate->TerminateExecution();
 54					++env.terminate_depth;
 55				}
 56			}
 57	
 58		private:
 59			State& state;
 60	};
