const r = await tools.exec_command({cmd:"node --no-node-snapshot -e '
const ivm=require("isolated-vm-next"); const {performance}=require("node:perf_hooks");
const source=`(() => { const c=globalThis.__ctx; let n=0; for (const [k,v] of Object.entries(c.candidate.metadata)) n += k.length + String(v).length; return {decision:"allow",patch:{seen:n}}; })()`;
function flat(bytes){return {op:"update",current:{id:1,metadata:{}},candidate:{id:1,metadata:{blob:"x".repeat(bytes)}},reads:{}}}
function wide(n){const m={};for(let i=0;i<n;i++)m["k"+i]="v"+i;return {op:"update",current:{id:1,metadata:{}},candidate:{id:1,metadata:m},reads:{}}}
function s(name,a){a.sort((x,y)=>x-y);const q=p=>a[Math.min(a.length-1,Math.floor(a.length*p))];console.log(JSON.stringify({name,n:a.length,mean:+(a.reduce((x,y)=>x+y,0)/a.length).toFixed(3),p50:+q(.5).toFixed(3),p95:+q(.95).toFixed(3),p99:+q(.99).toFixed(3),max:+a.at(-1).toFixed(3)}));}
async function bench(name,p,n=500){const iso=new ivm.Isolate({memoryLimit:16});const script=await iso.compileScript(source);const a=[];for(let i=0;i<n;i++){const t=performance.now();const ctx=await iso.createContext();await ctx.global.set("__ctx",new ivm.ExternalCopy(p).copyInto());await script.run(ctx,{timeout:10,copy:true});ctx.release();a.push(performance.now()-t)}iso.dispose();s(name,a)}
(async()=>{await bench("fresh-context-flat-256KiB",flat(262144));await bench("fresh-context-flat-1MiB",flat(1048576));await bench("fresh-context-wide-10k",wide(10000));})().catch(e=>{console.error(e);process.exit(1)});'","workdir":"/Users/burakemre/Code/lobu","yield_time_ms":30000,"max_output_tokens":8000});
text(r.output);

