 945	/**
 946	 * Resolve + read a Behavior reaction script (`reactionFromFile(path)`): relative
 947	 * POSIX path under the config directory, ends in `.ts`, no `..` / absolute /
 948	 * backslash segments, ≤256KB. Ships RAW source — the server compiles it on
 949	 * receipt via `set_reaction_script`.
 950	 */
 951	function resolveReactionScript(
 952	  cwd: string,
 953	  watcherSlug: string,
 954	  rel: string
 955	): { sourcePath: string; sourceCode: string } {
 956	  const trimmed = rel.trim();
 957	  if (!trimmed) {
 958	    throw new ValidationError(
 959	      `Behavior "${watcherSlug}" \`reaction\` must be a path to a sibling .ts file (e.g. \`reaction: reactionFromFile("./reactions/foo.reaction.ts")\`)`
 960	    );
 961	  }
 962	  if (trimmed.startsWith("/") || trimmed.includes("\\")) {
 963	    throw new ValidationError(
 964	      `Behavior "${watcherSlug}" \`reaction\` must be a relative POSIX path (./foo.reaction.ts) — absolute paths and backslashes are not allowed`
 965	    );
 966	  }
 967	  if (trimmed.split("/").some((seg) => seg === "..")) {
 968	    throw new ValidationError(
 969	      `Behavior "${watcherSlug}" \`reaction\` must not contain \`..\` segments — keep the script under the config directory`
 970	    );
 971	  }
 972	  if (!trimmed.endsWith(".ts")) {
 973	    throw new ValidationError(
 974	      `Behavior "${watcherSlug}" \`reaction\` must end in \`.ts\` (got ${JSON.stringify(trimmed)})`
 975	    );
 976	  }
 977	  const baseDir = resolve(cwd);
 978	  const abs = resolve(baseDir, trimmed);
 979	  // Containment check via `relative` (cross-platform): a hard-coded `${baseDir}/`
 980	  // prefix uses POSIX `/` and wrongly rejects every path on Windows (backslash
